Contract GenerateLoanLetterAndAgreementModule::createLoanAccount(loanaccountid:Integer,balance:Real,status:LoanAccountStatus[NORMAL|HASPAIDINFULL]): Boolean {
          definition:
          la:LoanAccount = LoanAccount.allInstance()->any(o | o.LoanAccountID = loanaccountid)


            postcondition:
          if la.oclIsUndefined() then let newLA:LoanAccount in newLA.oclIsNew() and LoanAccount.allInstance()->includes(newLA) and newLA.LoanAccountID = loanaccountid and newLA.Balance = balance and newLA.Status = status and result = true else result = false endif

        }
